application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600&display=swap');

:root { --ink:#17252b; --muted:#718087; --line:#dfe8e7; --teal:#167b78; --teal-dark:#105f5d; --mint:#eef8f5; --coral:#db7869; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); background:#f5f8f7; font-family:'DM Sans',sans-serif; }
.shell { max-width:1100px; margin:auto; padding:58px 28px 30px; }
.hero { display:flex; align-items:center; gap:18px; margin-bottom:42px; }
.brand-mark { width:46px; height:46px; display:grid; place-items:center; color:white; background:var(--teal); border-radius:14px; font-size:25px; box-shadow:0 8px 20px #167b7830; }
.eyebrow,.section-label { color:var(--teal); font-size:11px; letter-spacing:1.8px; font-weight:700; margin:0 0 9px; }
h1,h2,p { margin-top:0; } h1 { font:600 40px 'Playfair Display',serif; margin-bottom:8px; letter-spacing:-.7px; } h2 { font-size:22px; margin:0; letter-spacing:-.3px; }
.subtitle { color:var(--muted); margin:0; font-size:14px; }
.layout { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:24px; align-items:start; }
.card { background:white; border:1px solid #e7eeee; border-radius:20px; box-shadow:0 12px 35px #193c4010; padding:30px; }
.card-heading,.list-header { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:25px; }.step { color:#9caeb0; font-size:12px; font-weight:600; }
.field { margin-bottom:18px; flex:1; } label { display:block; font-size:12px; font-weight:700; margin:0 0 8px; color:#405258; }
input,select { width:100%; border:1px solid var(--line); border-radius:9px; padding:13px 14px; background:#fbfdfd; color:var(--ink); font:14px 'DM Sans',sans-serif; outline:none; transition:.2s; } input:focus,select:focus { border-color:var(--teal); box-shadow:0 0 0 3px #167b7815; } input:invalid:not(:placeholder-shown) { border-color:#d99084; }
.field-row { display:flex; gap:14px; } .primary-button { border:0; border-radius:9px; width:100%; padding:14px; margin-top:5px; color:white; background:var(--teal); font:700 14px 'DM Sans',sans-serif; cursor:pointer; transition:.2s; } .primary-button:hover { background:var(--teal-dark); transform:translateY(-1px); } .primary-button span { font-size:19px; vertical-align:-1px; margin-left:8px; }
.confirmation { background:#eaf8f0; color:#21714c; border:1px solid #c8ead6; border-radius:9px; padding:12px 14px; font-size:13px; margin-top:18px; }
.count { background:var(--mint); color:var(--teal); min-width:28px; height:28px; border-radius:20px; display:grid; place-items:center; font-size:12px; font-weight:700; }.booking-list { display:flex; flex-direction:column; gap:12px; }.empty-state { min-height:270px; display:flex; flex-direction:column; align-items:center; justify-content:center; color:var(--muted); text-align:center; gap:7px; font-size:13px; }.empty-state strong { color:var(--ink); font-size:14px; }.calendar-icon { color:var(--teal); font-size:45px; line-height:1; margin-bottom:6px; opacity:.75; }
.booking { border:1px solid var(--line); border-radius:12px; padding:16px; position:relative; background:#fff; }.booking.cancelled { opacity:.62; background:#fafbfb; }.booking-top { display:flex; justify-content:space-between; gap:10px; }.booking-name { font-weight:700; font-size:15px; }.booking-type { color:var(--teal); font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.7px; margin-top:4px; }.booking-details { display:flex; gap:14px; flex-wrap:wrap; color:var(--muted); font-size:12px; margin-top:14px; }.cancel-button { color:var(--coral); background:none; border:0; cursor:pointer; font:600 12px 'DM Sans'; padding:0; }.cancelled-label { color:#879395; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; }.booking.cancelled .booking-name { text-decoration:line-through; } footer { text-align:center; color:#9aa9aa; font-size:12px; margin-top:28px; } footer span { margin:0 8px; }
@media (max-width:720px) { .shell { padding:35px 17px 25px; } h1 { font-size:32px; }.layout { grid-template-columns:1fr; }.card { padding:23px; } }
@media (max-width:420px) { .field-row { flex-direction:column; gap:0; } }

application.javascript:
const form = document.getElementById('booking-form');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('confirmation');
const count = document.getElementById('booking-count');
const dateInput = document.querySelector('[data-testid="booking-date"]');

const today = new Date();
const localToday = new Date(today.getTime() - today.getTimezoneOffset() * 60000).toISOString().split('T')[0];
dateInput.min = localToday;

function updateCount() {
  count.textContent = list.querySelectorAll('[data-status="active"]').length;
}

function formatDate(value) {
  return new Date(`${value}T00:00:00`).toLocaleDateString(undefined, { weekday:'short', month:'short', day:'numeric', year:'numeric' });
}

function formatTime(value) {
  const [hours, minutes] = value.split(':');
  const d = new Date();
  d.setHours(hours, minutes);
  return d.toLocaleTimeString([], { hour:'numeric', minute:'2-digit' });
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.checkValidity()) { form.reportValidity(); return; }
  const data = new FormData(form);
  if (data.get('date') < localToday) {
    dateInput.setCustomValidity('Please choose today or a future date.');
    dateInput.reportValidity();
    dateInput.setCustomValidity('');
    return;
  }

  emptyState.hidden = true;
  const booking = document.createElement('article');
  booking.className = 'booking';
  booking.dataset.testid = 'booking';
  booking.dataset.status = 'active';
  booking.innerHTML = `<div class="booking-top"><div><div class="booking-name" data-testid="booking-name-display"></div><div class="booking-type"></div></div><button class="cancel-button" data-testid="booking-cancel" type="button">Cancel</button></div><div class="booking-details"><span>◷ <b class="booking-date"></b></span><span>◉ <b class="booking-time"></b></span></div>`;
  booking.querySelector('[data-testid="booking-name-display"]').textContent = data.get('name');
  booking.querySelector('.booking-type').textContent = data.get('type');
  booking.querySelector('.booking-date').textContent = formatDate(data.get('date'));
  booking.querySelector('.booking-time').textContent = formatTime(data.get('time'));
  booking.querySelector('[data-testid="booking-cancel"]').addEventListener('click', () => {
    booking.dataset.status = 'cancelled';
    booking.classList.add('cancelled');
    const button = booking.querySelector('[data-testid="booking-cancel"]');
    button.outerHTML = '<span class="cancelled-label">Cancelled</span>';
    updateCount();
  });
  list.prepend(booking);
  updateCount();
  confirmation.textContent = `Appointment confirmed for ${data.get('name')}.`;
  confirmation.hidden = false;
  form.reset();
  setTimeout(() => { confirmation.hidden = true; }, 5000);
});

dateInput.addEventListener('input', () => dateInput.setCustomValidity(''));
